-- PREPARED -- NOT APPLIED.
--
-- MICHELIN Guide, mainland China (CN): bring every CN restaurant's stars and
-- award_history in line with MICHELIN's live "Chinese Mainland" listing, add
-- the starred restaurants and Key hotels missing from the catalogue, link
-- restaurants to Key hotels where MICHELIN's own addresses agree, and complete
-- existing rows (fill-only). Mainland China is five guides published at
-- different times; each award row carries its own guide's edition:
--   Beijing & Tianjin 2027 (27 Oct 2026), Chengdu 2027 (3 Sep 2026),
--   Guangzhou & Shenzhen 2026 (18 Aug 2026), Shanghai, Jiangsu & Zhejiang 2026
--   (9 Apr 2026), Fujian 2026 (21 Nov 2025); Keys 2026 (18 Sep 2026).
-- Generated by build_prepared.py; evidence and every judgement call in
-- match_report.csv and README.md.
--
-- Summary: {"address_on_own_site": {"hotel_confirmed": 44, "hotel_site_unreachable": 10, "restaurant_confirmed": 67, "restaurant_differs": 1, "restaurant_no_official_site": 80, "restaurant_not_found": 7, "restaurant_site_unreachable": 4}, "point_fixes": 5, "existing": 3, "matched": 3, "changes": 0, "corrections": 0, "new": 156, "new_phones": 40, "new_websites": 78, "new_place_ids": 0, "property_names": 24, "links": 15, "fills": 2, "new_hotels": 51, "new_hotel_phones": 41, "new_hotel_websites": 41, "key_changes": 1, "hotel_fills": 0, "keys_not_in_2026": 0}
--
-- PREREQUISITE: supabase/migrations/20261023150000_add_cn_2026_star_and_key_cities.sql.
-- One transaction; every check raises and rolls the whole file back.
-- Run: supabase db query --linked -f <absolute path to this file>

begin;

do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'CN';
  if n <> 3 then raise exception 'CN: expected 3 restaurants (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from (values ('rest_0471', 'Xin Rong Ji (Xinyuan South Road)'), ('rest_0472', 'King''s Joy'), ('rest_1375', 'Fu He Hui')) e(code, name)
   where not exists (select 1 from public.restaurants r where r.restaurant_code = e.code and r.name = e.name and r.country_code = 'CN');
  if n <> 0 then raise exception 'CN: % exported restaurant codes no longer carry their exported name', n; end if;
  select count(*) into n from public.hotels where country_code = 'CN';
  if n <> 3 then raise exception 'CN: expected 3 hotels (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from (values ('hotel_704', 'Mandarin Oriental Qianmen'), ('hotel_796', 'Mandarin Oriental Shenzhen'), ('hotel_800', 'The Peninsula Shanghai')) e(code, name)
   where not exists (select 1 from public.hotels h where h.hotel_code = e.code and h.name = e.name and h.country_code = 'CN');
  if n <> 0 then raise exception 'CN: % exported hotel codes no longer carry their exported name', n; end if;
  if exists (select 1 from public.restaurants where restaurant_code ~ '^rest_[0-9]+$'
              and substring(restaurant_code from 6)::int between 2659 and 2814) then
    raise exception 'restaurant codes rest_2659..rest_2814 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.hotels where hotel_code ~ '^hotel_[0-9]+$'
              and substring(hotel_code from 7)::int between 957 and 1007) then
    raise exception 'hotel codes hotel_957..hotel_1007 are no longer free -- re-check';
  end if;
  if (select count(distinct guide_year) from public.award_history where award_type = 'michelin_keys' and is_current) > 1
     or exists (select 1 from public.award_history where award_type = 'michelin_keys' and is_current and guide_year <> 2026) then
    raise exception 'current michelin_keys rows are not all guide_year 2026 -- decide the year explicitly';
  end if;
end $$;

-- 1. MICHELIN Key hotels missing from `hotels` (each with its current 2026 Key row).
--    Points: MICHELIN's GCJ-02 pin converted to WGS-84 (README "Coordinates"; raw pin in cn_key_hotels_2026.csv).
create temp table _new_hotels_cn (code text, name text, keys smallint, city text, address text, lon float8, lat float8,
                               michelin_url text, website_url text, phone text) on commit drop;
do $$
declare bad text;
begin
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_hotels_cn x
   where (select count(*) from public.cities c where c.country_code = 'CN' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'hotel city does not resolve to exactly one CN row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_hotels_cn x join public.hotels h on h.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'hotel already present (michelin_url): %', bad; end if;
end $$;
select x.code, x.name, x.keys,
       (select c.id from public.cities c where c.country_code = 'CN' and c.name = x.city), 'CN',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone
  from _new_hotels_cn x;

-- 1b. Key changes on existing hotels (NULL-safe: a World's 50 Best hotel may hold no Key yet)
create temp table _kchg_cn (code text primary key, keys smallint, was smallint) on commit drop;
update public.award_history a set is_current = false from public.hotels h, _kchg_cn k
 where h.id = a.entity_id and h.hotel_code = k.code and a.entity_type = 'hotel' and a.award_type = 'michelin_keys' and a.is_current;
update public.hotels h set michelin_keys = k.keys, updated_at = now() from _kchg_cn k
 where h.hotel_code = k.code and h.michelin_keys is not distinct from k.was;

-- 1c. current 2026 Key row for every CN Key hotel that lacks one
select 'hotel', h.id, 2026, 'michelin_keys', h.michelin_keys, true, date '2026-09-18'
  from public.hotels h
 where h.hotel_code = any(array['hotel_704', 'hotel_957', 'hotel_958', 'hotel_959', 'hotel_960', 'hotel_961', 'hotel_962', 'hotel_963', 'hotel_796', 'hotel_964', 'hotel_965', 'hotel_800', 'hotel_966', 'hotel_967', 'hotel_968', 'hotel_969', 'hotel_970', 'hotel_971', 'hotel_972', 'hotel_973', 'hotel_974', 'hotel_975', 'hotel_976', 'hotel_977', 'hotel_978', 'hotel_979', 'hotel_980', 'hotel_981', 'hotel_982', 'hotel_983', 'hotel_984', 'hotel_985', 'hotel_986', 'hotel_987', 'hotel_988', 'hotel_989', 'hotel_990', 'hotel_991', 'hotel_992', 'hotel_993', 'hotel_994', 'hotel_995', 'hotel_996', 'hotel_997', 'hotel_998', 'hotel_999', 'hotel_1000', 'hotel_1001', 'hotel_1002', 'hotel_1003', 'hotel_1004', 'hotel_1005', 'hotel_1006', 'hotel_1007'])
   and not exists (select 1 from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
                    and a.award_type = 'michelin_keys' and a.is_current);

-- 4. starred restaurants missing from the catalogue, each with its first award row in its own
--    guide's edition: 2026 (announced 2025-11-21): 7; 2026 (announced 2026-04-09): 75; 2026 (announced 2026-08-18): 27; 2027 (announced 2026-09-03): 15; 2027 (announced 2026-10-27): 32.
--    Place ID NULL: no Places API in this pass (QA).
create temp table _new_cn (code text, name text, stars smallint, city text, address text, lon float8, lat float8,
                        michelin_url text, website_url text, phone text, property_name text, place_id text,
                        guide_year smallint, announced_on date) on commit drop;
do $$
declare bad text;
begin
  select string_agg(x.code, ', ') into bad from _new_cn x join public.restaurants r on r.restaurant_code = x.code;
  if bad is not null then raise exception 'codes no longer free: %', bad; end if;
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_cn x
   where (select count(*) from public.cities c where c.country_code = 'CN' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'city does not resolve to exactly one CN row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_cn x join public.restaurants r on r.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'already present (michelin_url): %', bad; end if;
end $$;
                                address, location, michelin_url, website_url, phone, property_name, google_place_id)
select x.code, x.name, x.stars, 'michelin_star',
       (select c.id from public.cities c where c.country_code = 'CN' and c.name = x.city), 'CN',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone, x.property_name, x.place_id
  from _new_cn x;
select 'restaurant', r.id, x.guide_year, 'michelin_stars', x.stars, true, x.announced_on
  from _new_cn x join public.restaurants r on r.restaurant_code = x.code;

-- 5a. existing CN rows: production's points are Google's GCJ-02 (about 500 m off on the app's
--     OpenStreetMap tiles); each takes MICHELIN's WGS-84 point (README "Coordinates"; product owner,
--     2026-10-30: "google in China is not very accurate"). Guarded on the exported point (6 decimals).
create temp table _pt_cn (tbl text, code text, name text, lat0 float8, lon0 float8, lat float8, lon float8) on commit drop;
do $$
declare n int;
begin
  select count(*) into n from _pt_cn p
   where (p.tbl = 'restaurants' and not exists (select 1 from public.restaurants r where r.restaurant_code = p.code and r.name = p.name
            and round(ST_Y(r.location::geometry)::numeric, 6) = round(p.lat0::numeric, 6) and round(ST_X(r.location::geometry)::numeric, 6) = round(p.lon0::numeric, 6)))
      or (p.tbl = 'hotels' and not exists (select 1 from public.hotels h where h.hotel_code = p.code and h.name = p.name
            and round(ST_Y(h.location::geometry)::numeric, 6) = round(p.lat0::numeric, 6) and round(ST_X(h.location::geometry)::numeric, 6) = round(p.lon0::numeric, 6)));
  if n <> 0 then raise exception '% CN points changed since the export -- re-check', n; end if;
end $$;
update public.restaurants r set location = ST_SetSRID(ST_MakePoint(p.lon, p.lat), 4326)::geography, updated_at = now()
  from _pt_cn p where p.tbl = 'restaurants' and r.restaurant_code = p.code;
update public.hotels h set location = ST_SetSRID(ST_MakePoint(p.lon, p.lat), 4326)::geography, updated_at = now()
  from _pt_cn p where p.tbl = 'hotels' and h.hotel_code = p.code;

-- 5. existing restaurants, fill-only (never overwrites)
create temp table _fill_cn (code text primary key, phone text, website_url text, michelin_url text, property_name text) on commit drop;
update public.restaurants r set phone = f.phone, updated_at = now() from _fill_cn f where r.restaurant_code = f.code and f.phone is not null and r.phone is null;
update public.restaurants r set website_url = f.website_url, updated_at = now() from _fill_cn f where r.restaurant_code = f.code and f.website_url is not null and r.website_url is null;
update public.restaurants r set michelin_url = f.michelin_url, updated_at = now() from _fill_cn f where r.restaurant_code = f.code and f.michelin_url is not null and r.michelin_url is null;
update public.restaurants r set property_name = f.property_name, updated_at = now() from _fill_cn f where r.restaurant_code = f.code and f.property_name is not null and r.property_name is null
   and not exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);

-- 6. links to hotels in `hotels`
create temp table _links_cn (hotel_code text, restaurant_code text, confidence text, evidence text) on commit drop;
do $$
declare n int;
begin
  select count(*) into n from _links_cn l
   where not exists (select 1 from public.hotels h where h.hotel_code = l.hotel_code)
      or not exists (select 1 from public.restaurants r where r.restaurant_code = l.restaurant_code);
  if n <> 0 then raise exception '% links point at a missing hotel or restaurant', n; end if;
end $$;
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_cn l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- post-conditions: MICHELIN's live "Chinese Mainland" listing and the 2026 mainland China Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'CN' and michelin_stars = 3;
  if n <> 4 then raise exception 'expected 4 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'CN' and michelin_stars = 2;
  if n <> 24 then raise exception 'expected 24 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'CN' and michelin_stars = 1;
  if n <> 131 then raise exception 'expected 131 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'CN'
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception '% restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'CN' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception '% restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'CN' and r.restaurant_code between 'rest_2659' and 'rest_2814' and ah.guide_year = 2026;
  if n <> 109 then raise exception 'expected 109 new restaurants with a current 2026 row, found %', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'CN' and r.restaurant_code between 'rest_2659' and 'rest_2814' and ah.guide_year = 2027;
  if n <> 47 then raise exception 'expected 47 new restaurants with a current 2027 row, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'CN' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception '% restaurants have both a hotel link and a property_name', n; end if;
  select count(*) into n from public.hotels where country_code = 'CN' and michelin_keys = 3;
  if n <> 2 then raise exception 'expected 2 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'CN' and michelin_keys = 2;
  if n <> 11 then raise exception 'expected 11 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'CN' and michelin_keys = 1;
  if n <> 41 then raise exception 'expected 41 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'CN' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys) <> 1;
  if n <> 0 then raise exception '% Key hotels without exactly one matching current Key row', n; end if;
  select count(*) into n from public.hotel_restaurants hr join public.hotels h on h.id = hr.hotel_id where h.country_code = 'CN';
  if n <> 15 then raise exception 'expected 15 CN hotel links, found %', n; end if;
end $$;

commit;
